import copy
out=copy.deepcopy(grid)
# fill gaps between consecutive original 9s in each row and column
for r,row in enumerate(grid):
    cs=[c for c,x in enumerate(row) if x==9]
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b):
            if out[r][c]==1: out[r][c]=2
for c in range(15):
    rs=[r for r in range(21) if grid[r][c]==9]
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b):
            if out[r][c]==1: out[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in out))
print('new',sum(x==2 for row in out for x in row))

# Build rule inferred: fill gaps only along a row/col containing an adjacent original pair; additionally
# fill top/bottom occupied rows and left/right occupied columns across the full foreground bbox.
fg=[(r,c) for r in range(21) for c in range(15) if grid[r][c]==9]
rmin,rmax=min(r for r,c in fg),max(r for r,c in fg)
cmin,cmax=min(c for r,c in fg),max(c for r,c in fg)
out2=copy.deepcopy(grid)
# boundary rows fully span x bbox
for r in {rmin,rmax}:
    for c in range(cmin,cmax+1):
        if out2[r][c]==1: out2[r][c]=2
# interior rows with any adjacent original 9 pair fill min..max
for r in range(rmin,rmax+1):
    cs=[c for c in range(15) if grid[r][c]==9]
    if any(b==a+1 for a,b in zip(cs,cs[1:])):
        for c in range(min(cs),max(cs)+1):
            if out2[r][c]==1: out2[r][c]=2
# boundary columns full span y bbox
for c in {cmin,cmax}:
    for r in range(rmin,rmax+1):
        if out2[r][c]==1: out2[r][c]=2
# interior cols with adjacent original 9 pair fill min..max
for c in range(cmin,cmax+1):
    rs=[r for r in range(21) if grid[r][c]==9]
    if any(b==a+1 for a,b in zip(rs,rs[1:])):
        for r in range(min(rs),max(rs)+1):
            if out2[r][c]==1: out2[r][c]=2
print('bounds',rmin,rmax,cmin,cmax)
print('\n'.join(' '.join(map(str,row)) for row in out2))

out3=copy.deepcopy(grid)
active_rows={rmin,rmax}
for r in range(21):
    cs=[c for c in range(15) if grid[r][c]==9]
    if any(b==a+1 for a,b in zip(cs,cs[1:])): active_rows.add(r)
active_cols={cmin,cmax}
for c in range(15):
    rs=[r for r in range(21) if grid[r][c]==9]
    if any(b==a+1 for a,b in zip(rs,rs[1:])): active_cols.add(c)
print(active_rows,active_cols)
# Complete strokes on those lines across the span of all active perpendicular lines.
for r in active_rows:
    for c in range(min(active_cols),max(active_cols)+1):
        if out3[r][c]==1: out3[r][c]=2
for c in active_cols:
    for r in range(min(active_rows),max(active_rows)+1):
        if out3[r][c]==1: out3[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in out3))
